test.describe('ads.html — VMAP schedule', () => {
  test.beforeEach(async ({ page }) => {
    await loadExample(page, '/examples/ads.html');
  });

  test('player wrapper is present', async ({ page }) => {
    await expect(page.locator(sel.wrapper)).toBeVisible();
