import json
d = json.load(open('UI_GRAPH.json'))

# Find edge endpoints not in node IDs
node_ids = {n['id'] for n in d['nodes']}
missing = set()
for e in d['edges']:
    if e['from'] not in node_ids:
        missing.add(('from', e['from']))
    if e['to'] not in node_ids:
        missing.add(('to', e['to']))

if missing:
    print('MISSING NODES referenced in edges:')
    for m in sorted(missing):
        print(' ', m)
else:
    print('All edge endpoints have matching nodes ✓')

# Check every node except root has at least one incoming edge
incoming = {e['to'] for e in d['edges']}
no_incoming = [n['id'] for n in d['nodes'] if n['id'] not in incoming and n['id'] != '/']
if no_incoming:
    print('Nodes with no incoming edge (not reachable from root):')
    for nid in no_incoming:
        print(' ', nid)
else:
    print('All non-root nodes are reachable ✓')
"

